const config = $('Workflow Configuration').first().json;
const rows = $input.all().map(item => item.json);
const staticData = $getWorkflowStaticData('global');

staticData.postgresPineconeSync = staticData.postgresPineconeSync || {};
staticData.postgresPineconeSync.tableState = staticData.postgresPineconeSync.tableState || {};
staticData.postgresPineconeSync.currentRun = {
  startedAt: new Date().toISOString(),
  discoveredColumns: rows.length,
  discoveredTables: 0,
  candidateTables: 0,
  skippedTables: [],
};

const parseList = (value) => String(value || '').split(',').map(v => v.trim()).filter(Boolean);
const allowedSchemas = parseList(config.allowedSchemas);
const allowedTables = parseList(config.allowedTables).map(v => v.toLowerCase());
const excludedTables = parseList(config.excludedTables).map(v => v.toLowerCase());
const configuredExcludedColumns = parseList(config.excludedColumns).map(v => v.toLowerCase());
const sensitivePatterns = ['password', 'passwd', 'pwd', 'token', 'secret', 'api_key', 'apikey', 'access_key', 'refresh_token', 'reset_token', 'otp', 'pin', 'session', 'cookie', 'hash', 'salt', 'private_key', 'client_secret'];
const timestampCandidates = ['updated_at', 'modified_at', 'last_modified', 'created_at'];
const textTypes = new Set(['text', 'character varying', 'varchar', 'character', 'char', 'json', 'jsonb']);
const scalarTypes = new Set(['integer', 'bigint', 'smallint', 'numeric', 'decimal', 'real', 'double precision', 'boolean', 'date', 'timestamp without time zone', 'timestamp with time zone', 'uuid']);
const maxRows = Math.max(1, Number(config.maxRowsPerTable || 500));
const minTextColumns = Math.max(1, Number(config.minTextColumns || 1));
const namespacePrefix = String(config.pineconeNamespacePrefix || 'postgres-');

function tableKey(schema, table) { return `${schema}.${table}`; }
function quoteIdent(value) { return '"' + String(value).replace(/"/g, '""') + '"'; }
function quoteLiteral(value) { return "'" + String(value).replace(/'/g, "''") + "'"; }
function isSensitiveColumn(columnName) {
  const lower = String(columnName || '').toLowerCase();
  return sensitivePatterns.some(pattern => lower.includes(pattern)) || configuredExcludedColumns.includes(lower);
}
function isAllowedTable(schema, table) {
  const key = tableKey(schema, table).toLowerCase();
  const tableOnly = String(table).toLowerCase();
  if (allowedSchemas.length && !allowedSchemas.includes(schema)) return false;
  if (allowedTables.length && !allowedTables.includes(key) && !allowedTables.includes(tableOnly)) return false;
  if (excludedTables.includes(key) || excludedTables.includes(tableOnly)) return false;
  return true;
}

const tables = new Map();
for (const row of rows) {
  const schema = row.table_schema;
  const table = row.table_name;
  if (!schema || !table) continue;
  const key = tableKey(schema, table);
  if (!tables.has(key)) tables.set(key, { schema, table, columns: [] });
  tables.get(key).columns.push(row);
}

staticData.postgresPineconeSync.currentRun.discoveredTables = tables.size;
const outputs = [];
for (const [key, table] of tables.entries()) {
  if (!isAllowedTable(table.schema, table.table)) {
    staticData.postgresPineconeSync.currentRun.skippedTables.push({ table: key, reason: 'Filtered by allowed/excluded table settings' });
    continue;
  }
  const safeColumns = table.columns.filter(col => !isSensitiveColumn(col.column_name));
  const primaryKeys = safeColumns.filter(col => col.is_primary_key === true || col.is_primary_key === 'true').map(col => col.column_name);
  const primaryKey = primaryKeys[0];
  if (!primaryKey && config.skipTablesWithoutPrimaryKey) {
    staticData.postgresPineconeSync.currentRun.skippedTables.push({ table: key, reason: 'No primary key detected' });
    continue;
  }
  const timestampColumn = timestampCandidates.find(candidate => safeColumns.some(col => String(col.column_name).toLowerCase() === candidate)) || null;
  const textColumns = safeColumns.filter(col => textTypes.has(String(col.data_type).toLowerCase()) || textTypes.has(String(col.udt_name).toLowerCase())).map(col => col.column_name).filter(col => col !== primaryKey);
  if (textColumns.length < minTextColumns) {
    staticData.postgresPineconeSync.currentRun.skippedTables.push({ table: key, reason: 'No useful text/json columns detected' });
    continue;
  }
  if (!timestampColumn && !config.fullSyncTablesWithoutTimestamp) {
    staticData.postgresPineconeSync.currentRun.skippedTables.push({ table: key, reason: 'No timestamp column and full sync fallback is disabled' });
    continue;
  }
  const scalarColumns = safeColumns.filter(col => scalarTypes.has(String(col.data_type).toLowerCase())).map(col => col.column_name);
  const selectedColumns = [...new Set([primaryKey, timestampColumn, ...textColumns, ...(config.includeScalarContextColumns ? scalarColumns : [])].filter(Boolean))];
  const state = staticData.postgresPineconeSync.tableState[key] || {};
  const lastSync = state.lastSync || config.defaultLastSync || '1970-01-01T00:00:00.000Z';
  const schemaSql = quoteIdent(table.schema);
  const tableSql = quoteIdent(table.table);
  const orderSql = timestampColumn ? `ORDER BY ${quoteIdent(timestampColumn)} ASC` : `ORDER BY ${quoteIdent(primaryKey)} ASC`;
  const whereSql = timestampColumn ? `WHERE ${quoteIdent(timestampColumn)} > ${quoteLiteral(lastSync)}` : '';
  const namespace = `${namespacePrefix}${table.schema}.${table.table}`;
  const fetchSql = [
    'SELECT',
    `  ${quoteLiteral(table.schema)} AS "__n8n_schema",`,
    `  ${quoteLiteral(table.table)} AS "__n8n_table",`,
    `  ${quoteLiteral(primaryKey || '')} AS "__n8n_primary_key",`,
    `  ${quoteLiteral(timestampColumn || '')} AS "__n8n_timestamp_column",`,
    `  ${quoteLiteral(JSON.stringify(textColumns))} AS "__n8n_text_columns",`,
    `  ${quoteLiteral(JSON.stringify(selectedColumns))} AS "__n8n_selected_columns",`,
    `  ${quoteLiteral(namespace)} AS "__n8n_namespace",`,
    `  ${quoteLiteral(key)} AS "__n8n_table_key",`,
    '  row_to_json(src)::jsonb AS "__n8n_row"',
    `FROM (SELECT * FROM ${schemaSql}.${tableSql} ${whereSql} ${orderSql} LIMIT ${maxRows}) src;`,
  ].join('\n');
  outputs.push({ json: { tableKey: key, schema: table.schema, table: table.table, primaryKey, timestampColumn, textColumns, selectedColumns, namespace, lastSync, fetchSql } });
}
staticData.postgresPineconeSync.currentRun.candidateTables = outputs.length;
return outputs;

const config = $('Workflow Configuration').first().json;
const maxChars = Math.max(1000, Number(config.maxDocumentCharacters || 12000));
const sourceName = String(config.sourceName || 'postgres');
function parseJson(value, fallback) { if (Array.isArray(value)) return value; if (value && typeof value === 'object') return value; try { return JSON.parse(value); } catch (error) { return fallback; } }
function titleCase(value) { return String(value).replace(/_/g, ' ').replace(/\w\S*/g, word => word.charAt(0).toUpperCase() + word.slice(1)); }
function normalizeValue(value) { if (value === null || value === undefined) return ''; if (value instanceof Date) return value.toISOString(); if (typeof value === 'object') return JSON.stringify(value); return String(value); }
const documents = [];
for (const item of $input.all()) {
  const row = parseJson(item.json.__n8n_row, {});
  const schema = item.json.__n8n_schema;
  const table = item.json.__n8n_table;
  const primaryKey = item.json.__n8n_primary_key;
  const timestampColumn = item.json.__n8n_timestamp_column || null;
  const selectedColumns = parseJson(item.json.__n8n_selected_columns, []);
  const textColumns = parseJson(item.json.__n8n_text_columns, []);
  const namespace = item.json.__n8n_namespace;
  const tableKey = item.json.__n8n_table_key;
  const primaryKeyValue = primaryKey ? row[primaryKey] : undefined;
  if (primaryKey && (primaryKeyValue === undefined || primaryKeyValue === null || primaryKeyValue === '')) continue;
  const lines = [`Database: ${sourceName}`, `Schema: ${schema}`, `Table: ${table}`];
  for (const column of selectedColumns) {
    if (!Object.prototype.hasOwnProperty.call(row, column)) continue;
    const value = normalizeValue(row[column]);
    if (!value) continue;
    lines.push(`${titleCase(column)}: ${value}`);
  }
  let document = lines.join('\n');
  if (document.length > maxChars) document = document.slice(0, maxChars) + '\n[Document truncated to configured maximum length]';
  const updatedAt = timestampColumn && row[timestampColumn] ? normalizeValue(row[timestampColumn]) : null;
  const vectorId = `${sourceName}::${schema}::${table}::${primaryKeyValue}`;
  documents.push({ json: { id: vectorId, document, namespace, tableKey, timestampColumn, updatedAt, metadata: { source: sourceName, schema, table, primary_key: primaryKey, primary_key_value: normalizeValue(primaryKeyValue), updated_at: updatedAt, text_columns: textColumns.join(','), document_columns: selectedColumns.join(',') } } });
}
return documents;

const config = $('Workflow Configuration').first().json;
const allDocs = $input.all().map(item => item.json).filter(doc => doc.document);
const smokeTestMode = config.geminiSmokeTestMode !== false;
const maxDocuments = smokeTestMode ? 1 : Math.max(1, Number(config.maxDocumentsPerRun || 10));
const docs = allDocs.slice(0, maxDocuments);
const batchSize = Math.max(1, Math.min(100, Number(config.geminiBatchSize || 1)));
const staticData = $getWorkflowStaticData('global');
staticData.postgresPineconeSync = staticData.postgresPineconeSync || {};
staticData.postgresPineconeSync.currentRun = staticData.postgresPineconeSync.currentRun || {};
staticData.postgresPineconeSync.currentRun.geminiSmokeTestMode = smokeTestMode;
staticData.postgresPineconeSync.currentRun.embeddingDocumentsPrepared = docs.length;
staticData.postgresPineconeSync.currentRun.embeddingDocumentsSkippedByRunLimit = Math.max(0, allDocs.length - docs.length);
const batches = [];

for (let i = 0; i < docs.length; i += batchSize) {
  const documents = docs.slice(i, i + batchSize);
  batches.push({
    json: {
      input: documents.map(doc => doc.document),
      documents,
      documentCount: documents.length,
    },
  });
}

return batches;

const config = $('Workflow Configuration').first().json;
const embeddingBatches = $items('Prepare Gemini Embedding Batches');
const responses = $input.all();
const batchSize = Math.max(1, Math.min(100, Number(config.pineconeBatchSize || 50)));
const groups = new Map();

function isEmbedding(value) {
  return Array.isArray(value) && value.length > 0 && value.every(v => typeof v === 'number');
}

for (let batchIndex = 0; batchIndex < responses.length; batchIndex++) {
  const response = responses[batchIndex].json;
  const sourceBatch = embeddingBatches[batchIndex]?.json;
  const documents = sourceBatch?.documents || [];
  const embeddings = Array.isArray(response?.embeddings) ? response.embeddings : [];

  if (documents.length && embeddings.length !== documents.length) {
    throw new Error(`Gemini returned ${embeddings.length} embeddings for ${documents.length} documents in batch ${batchIndex}. Stopping before Pinecone upsert.`);
  }
  if (!documents.length || !embeddings.length) continue;

  for (let docIndex = 0; docIndex < documents.length; docIndex++) {
    const doc = documents[docIndex];
    const embedding = embeddings[docIndex]?.values;
    if (!doc || !isEmbedding(embedding)) continue;

    const groupKey = `${doc.namespace}::${doc.tableKey}`;
    if (!groups.has(groupKey)) {
      groups.set(groupKey, {
        namespace: doc.namespace,
        tableKey: doc.tableKey,
        timestampColumn: doc.timestampColumn,
        pineconeIndexHost: config.pineconeIndexHost,
        vectors: [],
        maxTimestamp: null,
      });
    }

    const group = groups.get(groupKey);
    group.vectors.push({ id: doc.id, values: embedding, metadata: doc.metadata });

    if (doc.updatedAt) {
      const next = new Date(doc.updatedAt).toISOString();
      if (!group.maxTimestamp || next > group.maxTimestamp) group.maxTimestamp = next;
    }
  }
}

const output = [];
for (const group of groups.values()) {
  for (let i = 0; i < group.vectors.length; i += batchSize) {
    const vectors = group.vectors.slice(i, i + batchSize);
    output.push({
      json: {
        namespace: group.namespace,
        tableKey: group.tableKey,
        timestampColumn: group.timestampColumn,
        maxTimestamp: group.maxTimestamp,
        pineconeIndexHost: group.pineconeIndexHost,
        vectorCount: vectors.length,
        vectors,
      },
    });
  }
}

return output;

const staticData = $getWorkflowStaticData('global');
staticData.postgresPineconeSync = staticData.postgresPineconeSync || {};
staticData.postgresPineconeSync.tableState = staticData.postgresPineconeSync.tableState || {};
const batches = $items('Prepare Pinecone Upsert Batches');
const responses = $input.all();
const currentRun = staticData.postgresPineconeSync.currentRun || {};
const summary = { startedAt: currentRun.startedAt, finishedAt: new Date().toISOString(), discoveredColumns: currentRun.discoveredColumns || 0, discoveredTables: currentRun.discoveredTables || 0, candidateTables: currentRun.candidateTables || 0, skippedTables: currentRun.skippedTables || [], geminiSmokeTestMode: currentRun.geminiSmokeTestMode || false, embeddingDocumentsPrepared: currentRun.embeddingDocumentsPrepared || 0, embeddingDocumentsSkippedByRunLimit: currentRun.embeddingDocumentsSkippedByRunLimit || 0, successfulBatches: 0, failedBatches: 0, vectorsUpserted: 0, updatedSyncState: {}, failedBatchDetails: [] };
function responseFailed(json) { if (!json) return true; if (json.error) return true; if (json.message && String(json.message).toLowerCase().includes('error')) return true; if (json.statusCode && Number(json.statusCode) >= 400) return true; return false; }
for (let index = 0; index < responses.length; index++) {
  const response = responses[index].json;
  const batch = batches[index]?.json;
  if (!batch) continue;
  if (responseFailed(response)) {
    summary.failedBatches += 1;
    summary.failedBatchDetails.push({ table: batch.tableKey, namespace: batch.namespace, error: response });
    continue;
  }
  summary.successfulBatches += 1;
  summary.vectorsUpserted += batch.vectorCount || batch.vectors?.length || 0;
  staticData.postgresPineconeSync.tableState[batch.tableKey] = staticData.postgresPineconeSync.tableState[batch.tableKey] || {};
  if (batch.timestampColumn && batch.maxTimestamp) {
    const previous = staticData.postgresPineconeSync.tableState[batch.tableKey].lastSync;
    if (!previous || batch.maxTimestamp > previous) staticData.postgresPineconeSync.tableState[batch.tableKey].lastSync = batch.maxTimestamp;
  } else {
    staticData.postgresPineconeSync.tableState[batch.tableKey].lastFullSync = new Date().toISOString();
  }
  staticData.postgresPineconeSync.tableState[batch.tableKey].lastNamespace = batch.namespace;
  staticData.postgresPineconeSync.tableState[batch.tableKey].lastSuccessfulRun = summary.finishedAt;
  summary.updatedSyncState[batch.tableKey] = staticData.postgresPineconeSync.tableState[batch.tableKey];
}
staticData.postgresPineconeSync.lastSummary = summary;
return [{ json: summary }];
